L373:             truncated_description_chars.saturating_add(description_char_count);
L374:         if description_char_count > 0 {
L375:             truncated_description_count = truncated_description_count.saturating_add(1);
L376:         }
L377:     }
L378: 
L379:     let report = skill_render_report(
L380:         total_count,
L381:         included.len(),
L382:         omitted_count,
L383:         truncated_description_chars,
L384:         truncated_description_count,
L385:     );
