L564:     let budget_lines = skill_lines
L565:         .iter()
L566:         .map(|line| DescriptionBudgetLine::new(line, budget))
L567:         .collect::<Vec<_>>();
L568:     let mut char_allocations = vec![0usize; budget_lines.len()];
L569:     let mut current_extra_costs = vec![0usize; budget_lines.len()];
L570:     let mut remaining = limit;
L571:     // Distribute description space one character at a time across skills.
L572:     // Short descriptions naturally drop out, so their unused share can go to
L573:     // longer descriptions instead of being stranded in a fixed per-skill quota.
L574:     loop {
L575:         let mut changed = false;
L576:         for (index, line) in budget_lines.iter().enumerate() {
