L578:                 continue;
L579:             }
L580:             let current_cost = current_extra_costs[index];
L581:             let next_chars = char_allocations[index].saturating_add(1);
L582:             let next_cost = line.extra_costs[next_chars];
L583:             let delta = next_cost.saturating_sub(current_cost);
L584:             if delta <= remaining {
L585:                 char_allocations[index] = next_chars;
L586:                 current_extra_costs[index] = next_cost;
L587:                 remaining = remaining.saturating_sub(delta);
L588:                 changed = true;
L589:             }
